import math
from collections.abc import Sequence
from numbers import Real


def smooth_series(samples, span, scheme):
    """Return a selected moving summary without modifying samples."""
    if isinstance(span, bool) or not isinstance(span, int) or span <= 0:
        raise ValueError("span must be a positive integer")
    if not isinstance(scheme, str) or scheme not in ("mean", "linear", "exponential"):
        raise ValueError("unknown scheme")
    if isinstance(samples, (str, bytes, bytearray)) or not isinstance(samples, Sequence):
        raise TypeError("samples must be a sequence")

    values = []
    for value in samples:
        if isinstance(value, bool) or not isinstance(value, Real):
            raise TypeError("samples must contain real numbers")
        try:
            number = float(value)
        except (OverflowError, ValueError) as exc:
            raise ValueError("samples must be finite") from exc
        if not math.isfinite(number):
            raise ValueError("samples must be finite")
        values.append(number)

    result = [None] * len(values)
    if len(values) < span:
        return result

    if scheme == "mean":
        for end in range(span - 1, len(values)):
            result[end] = sum(values[end - span + 1:end + 1]) / span
    elif scheme == "linear":
        denominator = span * (span + 1) / 2
        for end in range(span - 1, len(values)):
            window = values[end - span + 1:end + 1]
            result[end] = sum((i + 1) * value for i, value in enumerate(window)) / denominator
    else:
        seed_index = span - 1
        result[seed_index] = sum(values[:span]) / span
        alpha = 1 / span
        for index in range(span, len(values)):
            result[index] = alpha * values[index] + (1 - alpha) * result[index - 1]
    return result

